    38→          watcherStatus: project.watcherActive ? 'active' : 'stopped',
    39→        })),
    40→        total: projects.length,
    41→      };
    42→    })
    43→
    44→    // AC: @multi-directory-daemon ac-29 - Manual project registration
    45→    .post(
    46→      '/',
    47→      async ({ body, error: errorResponse }) => {
    48→        // AC: @multi-directory-daemon ac-29 - Accept {path: string} body
    49→        // Validate path is provided
    50→        if (!body.path || typeof body.path !== 'string' || body.path.trim().length === 0) {
    51→          return errorResponse(400, {
    52→            error: 'validation_error',
    53→            details: [
    54→              {
    55→                field: 'path',
    56→                message: 'Path is required and must be a non-empty string',
    57→              },
    58→            ],
    59→          });
    60→        }
    61→
    62→        // AC: @multi-directory-daemon ac-6 - Path must be absolute
    63→        if (!isAbsolute(body.path)) {
    64→          return errorResponse(400, {
    65→            error: 'Path must be absolute',
    66→          });
    67→        }
    68→
    69→        // AC: @multi-directory-daemon ac-7 - Reject parent traversal (..)
    70→        if (body.path.includes('..')) {
    71→          return errorResponse(400, {
    72→            error: 'Path must not contain parent traversal',
    73→          });
    74→        }
    75→
    76→        try {
    77→          // AC: @multi-directory-daemon ac-29 - Use ProjectContextManager.registerProject()
    78→          const context = projectManager.registerProject(body.path);
    79→
    80→          // Start watcher for the registered project
    81→          try {
    82→            await projectManager.startWatcher(body.path);
    83→          } catch (error: unknown) {
    84→            // AC: @multi-directory-daemon ac-19 - Handle OS limits
    85→            const message = error instanceof Error ? error.message : String(error);
    86→            if (message.includes('resource limit')) {
    87→              return errorResponse(503, {
    88→                error: 'Unable to watch project - resource limit reached',
    89→              });
    90→            }
    91→            throw error;
    92→          }
    93→
    94→          return {
    95→            success: true,
    96→            project: {
    97→              path: context.path,
    98→              registeredAt: context.registeredAt.toISOString(),
    99→              watcherStatus: context.watcherActive ? 'active' : 'stopped',
   100→            },
   101→          };
   102→        } catch (error: unknown) {
   103→          const message = error instanceof Error ? error.message : String(error);
   104→          const code = error instanceof Error && 'code' in error ? (error as NodeJS.ErrnoException).code : undefined;
   105→
   106→          // AC: @multi-directory-daemon ac-5 - Invalid project (no .kspec/)
   107→          if (message.includes('.kspec/ not found')) {
   108→            return errorResponse(400, {
   109→              error: `Invalid kspec project - .kspec/ not found at ${body.path}`,
   110→            });
   111→          }
   112→
   113→          // AC: @multi-directory-daemon ac-8b - Permission denied
   114→          if (code === 'EACCES' || code === 'EPERM') {
   115→            return errorResponse(403, {
   116→              error: `Permission denied - cannot read ${body.path}`,
   117→            });
   118→          }
   119→
   120→          // Generic error
   121→          return errorResponse(500, {
   122→            error: message || 'Failed to register project',
   123→          });
   124→        }
   125→      },
   126→      {
   127→        body: t.Object({
   128→          path: t.String(),
   129→        }),
   130→      }
   131→    )
   132→
   133→    // AC: @multi-directory-daemon ac-30 - Unregister project
   134→    .delete('/:encodedPath', async ({ params, error: errorResponse }) => {
   135→      // AC: @multi-directory-daemon ac-30 - Decode path from URL parameter
   136→      const projectPath = decodeURIComponent(params.encodedPath);
   137→
   138→      // Validate project exists
   139→      if (!projectManager.hasProject(projectPath)) {
   140→        return errorResponse(404, {
   141→          error: `Project not registered: ${projectPath}`,
   142→        });
   143→      }
   144→
   145→      try {
   146→        // AC: @multi-directory-daemon ac-30 - Stop file watcher
   147→        await projectManager.stopWatcher(projectPath);
   148→
   149→        // AC: @multi-directory-daemon ac-30 - Unregister project
   150→        projectManager.unregisterProject(projectPath);
   151→
   152→        return {
   153→          success: true,
   154→          message: `Project unregistered: ${projectPath}`,
   155→        };
   156→      } catch (error: unknown) {
   157→        return errorResponse(500, {
   158→          error: error instanceof Error ? error.message : 'Failed to unregister project',
   159→        });
   160→      }
   161→    });
   162→}
