		const task = fetchTaskStatic(ref);
		if (!task) {
			throw new Error(`Task not found: ${ref}`);
		}
		return task;
	}

	const response = await fetch(`${API_BASE}/api/tasks/${ref}`, {
		headers: getProjectHeaders()
	});
	if (!response.ok) {
		await handleResponseError(response);
	}

	return response.json();
}

