    28→ * Extracts X-Kspec-Dir header, validates path, registers/retrieves project,
    29→ * and attaches ProjectContext to request state.
    30→ *
    31→ * Returns both the manager (for external access) and the middleware function.
    32→ */
    33→export function projectContextMiddleware(options: ProjectContextMiddlewareOptions = {}) {
    34→  const manager = new ProjectContextManager(options.startupProject, options.pubsub);
    35→
    36→  // Register startup project if provided
    37→  // Note: Watcher will be started later after full initialization
    38→  if (options.startupProject) {
    39→    try {
    40→      manager.registerProject(options.startupProject, true);
    41→    } catch (error) {
    42→      console.warn(`[daemon] Failed to register startup project: ${error}`);
    43→    }
    44→  }
    45→
    46→  const middleware = (app: Elysia) =>
    47→    app
    48→      // Store manager in app state for WebSocket access
    49→      .state('projectManager', manager)
    50→      .derive(async ({ request, set }) => {
    51→        try {
    52→          // AC: @multi-directory-daemon ac-1 - Extract X-Kspec-Dir header
    53→          const projectPath = request.headers.get('X-Kspec-Dir') || undefined;
    54→
    55→          let projectContext: ProjectContext;
    56→
    57→          if (projectPath) {
    58→            // AC: @multi-directory-daemon ac-1, ac-4, ac-5, ac-6, ac-7, ac-8, ac-8b, ac-8c
    59→            // Try to get existing or register new project
    60→            try {
    61→              projectContext = manager.getProject(projectPath);
    62→            } catch (err) {
    63→              // Not registered - try to register (ac-4: auto-register)
    64→              projectContext = manager.registerProject(projectPath);
    65→              // Start watcher asynchronously (don't block request)
    66→              void manager.startWatcher(projectPath).catch((watcherError) => {
    67→                console.error(`[daemon] Failed to start watcher for ${projectPath}:`, watcherError);
    68→              });
    69→            }
    70→          } else {
    71→            // AC: @multi-directory-daemon ac-2, ac-3, ac-20b
    72→            // No header - use default project
    73→            projectContext = manager.getProject();
    74→          }
    75→
    76→          return { projectContext };
    77→        } catch (err: unknown) {
    78→          const message = err instanceof Error ? err.message : String(err);
    79→
    80→          // AC: @multi-directory-daemon ac-3, ac-20b
    81→          if (
    82→            message.includes('No default project configured') ||
    83→            message.includes('Default project no longer valid')
    84→          ) {
    85→            set.status = 400;
    86→            return { error: message };
    87→          }
    88→
    89→          // AC: @multi-directory-daemon ac-5
    90→          if (message.includes('Invalid kspec project')) {
    91→            set.status = 400;
    92→            return { error: message };
    93→          }
    94→
    95→          // AC: @multi-directory-daemon ac-6
    96→          if (message.includes('Path must be absolute')) {
    97→            set.status = 400;
    98→            return { error: 'Path must be absolute' };
    99→          }
   100→
   101→          // AC: @multi-directory-daemon ac-7
   102→          if (message.includes('Path must not contain parent traversal')) {
   103→            set.status = 400;
   104→            return { error: 'Path must not contain parent traversal' };
   105→          }
   106→
   107→          // AC: @multi-directory-daemon ac-8b - permission denied
   108→          if (message.includes('Permission denied')) {
   109→            set.status = 403;
   110→            return { error: message };
   111→          }
   112→
   113→          // AC: @multi-directory-daemon ac-19 - OS resource limits
   114→          if (message.includes('Unable to watch project - resource limit reached')) {
   115→            set.status = 503;
   116→            return { error: message };
   117→          }
   118→
   119→          // Other errors
   120→          set.status = 500;
   121→          return { error: 'Internal server error' };
   122→        }
   123→      });
   124→
   125→  return { manager, middleware };
   126→}
   127→
