 632→			tags?: string[];
 633→			priority?: number;
 634→		};
 635→	}>;
 636→	capabilities: string[];
 637→	tools: string[];
 638→	skills: string[];
 639→	budget?: {
 640→		max_tasks?: number;
 641→		timeout_minutes?: number;
 642→	};
 643→	concurrency: {
 644→		max_concurrent: number;
 645→	};
 646→	auto_approve: boolean;
 647→}
 648→
 649→/**
 650→ * Active invocation from GET /api/agent/status
 651→ */
 652→export interface ActiveInvocation {
 653→	session_id: string;
 654→	agent_id: string;
 655→	task_ref: string | null;
 656→	elapsed_ms: number;
 657→}
 658→
 659→/**
 660→ * Agent dispatch status from GET /api/agent/status
 661→ */
 662→export interface AgentDispatchStatus {
 663→	dispatch_enabled: boolean;
 664→	active_invocations: ActiveInvocation[];
 665→	queue_depth: number;
 666→	agent_definitions: Array<{
 667→		id: string;
 668→		name: string;
 669→		adapter: string;
 670→		completed_sessions?: number;
 671→	}>;
 672→}
 673→
 674→/**
 675→ * Fetch agent dispatch status (dispatch state + active invocations)
 676→ * AC: @ui-agent-dispatch ac-1, ac-2, ac-3
 677→ */
 678→export async function fetchAgentStatus(): Promise<AgentDispatchStatus> {
 679→	const response = await fetch(`${API_BASE}/api/agent/status`, {
 680→		headers: getProjectHeaders()
 681→	});
 682→	if (!response.ok) {
 683→		await handleResponseError(response);
 684→	}
 685→	return response.json();
 686→}
 687→
 688→/**
 689→ * Fetch full agent definitions from meta
 690→ * AC: @ui-agent-dispatch ac-1
 691→ */
 692→export async function fetchAgentDefinitions(): Promise<{ items: AgentDefinition[]; total: number }> {
 693→	const response = await fetch(`${API_BASE}/api/meta/agents`, {
 694→		headers: getProjectHeaders()
 695→	});
 696→	if (!response.ok) {
 697→		await handleResponseError(response);
 698→	}
 699→	return response.json();
 700→}
 701→
 702→/**
 703→ * Start or stop the dispatch engine
 704→ * AC: @ui-agent-dispatch ac-2
 705→ */
 706→export async function controlDispatch(action: 'start' | 'stop'): Promise<{ dispatch_enabled: boolean }> {
 707→	assertWritable('control dispatch');
 708→
 709→	const response = await fetch(`${API_BASE}/api/agent/dispatch`, {
 710→		method: 'POST',
 711→		headers: {
 712→			'Content-Type': 'application/json',
 713→			...getProjectHeaders()
 714→		},
 715→		body: JSON.stringify({ action })
 716→	});
 717→	if (!response.ok) {
 718→		await handleResponseError(response);
 719→	}
 720→	return response.json();
 721→}
 722→
 723→/**
 724→ * Execute a triage action
 725→ * AC: @interactive-triage-ui ac-3
 726→ */
 727→export async function actOnTriageRecord(
 728→	ref: string
 729→): Promise<{ success: boolean; record: TriageRecord }> {
 730→	assertWritable('execute triage action');
 731→
 732→	const response = await fetch(`${API_BASE}/api/triage/${ref}/act`, {
 733→		method: 'POST',
 734→		headers: getProjectHeaders()
 735→	});
 736→	if (!response.ok) {
 737→		await handleResponseError(response);
 738→	}
 739→
 740→	return response.json();
 741→}
 742→
 743→// ============================================================
 744→// Plans API Functions
 745→// AC: @ui-plans-view ac-1
 746→// ============================================================
 747→
 748→/**
 749→ * Fetch plans with optional status filter
 750→ * AC: @ui-plans-view ac-1
 751→ */
 752→export async function fetchPlans(params?: {
 753→	status?: string;
 754→}): Promise<{ items: PlanSummary[]; total: number }> {
 755→	if (isStaticMode()) {
 756→		return fetchPlansStatic(params);
 757→	}
 758→
 759→	const url = new URL(`${API_BASE}/api/plans`);
 760→
 761→	if (params) {
 762→		Object.entries(params).forEach(([key, value]) => {
 763→			if (value !== undefined && value !== '') {
 764→				url.searchParams.set(key, String(value));
 765→			}
 766→		});
 767→	}
 768→
 769→	const response = await fetch(url.toString(), {
 770→		headers: getProjectHeaders()
 771→	});
 772→	if (!response.ok) {
 773→		await handleResponseError(response);
 774→	}
 775→
 776→	return response.json();
 777→}
 778→
 779→// ============================================================
 780→// Workflows API Functions
 781→// AC: @ui-workflows-view ac-1
 782→// ============================================================
 783→
 784→/**
 785→ * Fetch workflow definitions
 786→ * AC: @ui-workflows-view ac-1
 787→ */
 788→export async function fetchWorkflows(): Promise<{ items: Workflow[]; total: number }> {
 789→	if (isStaticMode()) {
 790→		return fetchWorkflowsStatic();
 791→	}
 792→
 793→	const response = await fetch(`${API_BASE}/api/meta/workflows`, {
 794→		headers: getProjectHeaders()
 795→	});
 796→	if (!response.ok) {
 797→		await handleResponseError(response);
 798→	}
 799→
 800→	return response.json();
 801→}
 802→
 803→// ============================================================
 804→// Session API Functions
 805→// AC: @ui-session-stream ac-1, ac-2, ac-4
 806→// ============================================================
 807→
 808→/**
 809→ * Session summary from the daemon API.
 810→ */
 811→export interface SessionSummary {
 812→	id: string;
 813→	status: 'active' | 'completed' | 'abandoned' | 'timed_out' | 'failed';
 814→	agent_type: string;
 815→	session_type: 'loop' | 'invocation';
 816→	/** Dispatch trigger for distinguishing dispatched agent vs manual CLI run. */
 817→	trigger?: string;
 818→	/** Task ID being worked on (if any). AC: @ui-session-history ac-1 */
 819→	task_id?: string;
 820→	started_at: string;
 821→	ended_at?: string;
 822→	duration_ms: number;
 823→	event_count: number;
 824→	iteration_count: number;
 825→	tasks_completed: number;
 826→}
 827→
 828→/**
 829→ * Spec context with acceptance criteria checklist.
 830→ * AC: @ui-session-stream ac-4
 831→ */
 832→export interface SessionSpecContext {
 833→	spec_ref: string;
 834→	title: string;
 835→	acceptance_criteria: Array<{ id: string; description: string }>;
 836→}
 837→
 838→/**
 839→ * Session budget info.
 840→ * AC: @ui-session-stream ac-4
 841→ */
 842→export interface SessionBudget {
 843→	max_per_cycle: number;
 844→	started_this_cycle: number;
 845→}
 846→
 847→/**
 848→ * Session detail with additional metadata.
 849→ * AC: @ui-session-stream ac-4
 850→ */
 851→export interface SessionDetail extends SessionSummary {
 852→	task_id?: string;
 853→	agent_id?: string;
 854→	trigger?: string;
 855→	spec_context?: SessionSpecContext | null;
 856→	budget?: SessionBudget | null;
 857→}
 858→
 859→/**
 860→ * A single event from events.jsonl.
 861→ */
 862→export interface SessionEvent {
 863→	ts: number;
 864→	seq: number;
 865→	type: string;
 866→	session_id: string;
 867→	trace_id?: string;
 868→	data: unknown;
 869→}
 870→
 871→/**
 872→ * Fetch all sessions with summaries.
 873→ * AC: @ui-session-stream ac-1
 874→ */
 875→export async function fetchSessions(): Promise<{ items: SessionSummary[]; total: number }> {
 876→	if (isStaticMode()) {
 877→		return { items: [], total: 0 };
 878→	}
 879→
 880→	const response = await fetch(`${API_BASE}/api/sessions`, {
 881→		headers: getProjectHeaders()
 882→	});
 883→	if (!response.ok) {
 884→		await handleResponseError(response);
 885→	}
 886→
 887→	return response.json();
 888→}
 889→
 890→/**
 891→ * Fetch a single session by ID.
 892→ * AC: @ui-session-stream ac-4
 893→ */
 894→export async function fetchSession(id: string): Promise<SessionDetail> {
 895→	if (isStaticMode()) {
 896→		throw new Error('Session data not available in static mode');
 897→	}
 898→
 899→	const response = await fetch(`${API_BASE}/api/sessions/${id}`, {
 900→		headers: getProjectHeaders()
 901→	});
 902→	if (!response.ok) {
 903→		await handleResponseError(response);
 904→	}
 905→
 906→	return response.json();
 907→}
 908→
 909→/**
 910→ * Fetch session events (optionally incremental via since_seq).
 911→ * AC: @ui-session-stream ac-1, ac-2
 912→ */
 913→export async function fetchSessionEvents(
 914→	id: string,
 915→	sinceSeq?: number
 916→): Promise<{ events: SessionEvent[]; total: number }> {
 917→	if (isStaticMode()) {
 918→		return { events: [], total: 0 };
 919→	}
 920→
 921→	const url = new URL(`${API_BASE}/api/sessions/${id}/events`);
 922→	if (sinceSeq !== undefined) {
 923→		url.searchParams.set('since_seq', String(sinceSeq));
 924→	}
 925→
 926→	const response = await fetch(url.toString(), {
 927→		headers: getProjectHeaders()
 928→	});
 929→	if (!response.ok) {
 930→		await handleResponseError(response);
 931→	}
 932→
 933→	return response.json();
 934→}
 935→
 936→// ============================================================
 937→// Validation & Alignment API Functions
 938→// AC: @ui-validation-view ac-1
 939→// ============================================================
 940→
 941→export interface SchemaValidationError {
 942→	file: string;
 943→	path?: string;
 944→	message: string;
 945→	details?: unknown;
 946→}
 947→
 948→export interface RefValidationError {
 949→	ref: string;
 950→	sourceFile?: string;
 951→	sourceUlid?: string;
 952→	field: string;
 953→	error: 'not_found' | 'ambiguous' | 'duplicate_slug';
 954→	message: string;
 955→}
 956→
 957→export interface RefValidationWarning {
 958→	ref: string;
 959→	sourceFile?: string;
 960→	sourceUlid?: string;
 961→	field: string;
 962→	warning: 'deprecated_target';
 963→	message: string;
 964→}
 965→
 966→export interface OrphanItem {
 967→	ulid: string;
 968→	title: string;
 969→	type: string;
 970→	file?: string;
 971→}
 972→
 973→export type CompletenessWarningType =
 974→	| 'missing_acceptance_criteria'
 975→	| 'missing_description'
 976→	| 'status_inconsistency'
 977→	| 'missing_test_coverage'
 978→	| 'automation_eligible_no_spec'
 979→	| 'ac_schema_field_mismatch';
 980→
 981→export interface CompletenessWarning {
 982→	type: CompletenessWarningType;
 983→	subtype?: 'own_ac' | 'trait_ac';
 984→	itemRef: string;
 985→	itemTitle: string;
 986→	message: string;
 987→	details?: string;
 988→}
 989→
 990→export interface TraitCycleError {
 991→	traitRef: string;
 992→	traitTitle: string;
 993→	cycle: string[];
 994→	message: string;
 995→}
 996→
 997→export interface ValidationResponse {
 998→	valid: boolean;
 999→	schemaErrors: SchemaValidationError[];
1000→	refErrors: RefValidationError[];
1001→	refWarnings: RefValidationWarning[];
1002→	orphans: OrphanItem[];
1003→	completenessWarnings: CompletenessWarning[];
1004→	traitCycles: TraitCycleError[];
1005→}
1006→
1007→/** Alias for backward compatibility with dashboard overview */
1008→export type ValidationResult = ValidationResponse;
1009→
1010→export interface AlignmentWarning {
1011→	type: 'orphaned_spec' | 'status_mismatch' | 'stale_implementation';
1012→	specUlid?: string;
1013→	specTitle?: string;
1014→	taskUlid?: string;
1015→	message: string;
1016→}
1017→
1018→export interface AlignmentStats {
1019→	totalSpecs: number;
1020→	specsWithTasks: number;
1021→	alignedSpecs: number;
1022→	orphanedSpecs: number;
1023→}
1024→
1025→export interface AlignmentResponse {
1026→	stats: AlignmentStats;
1027→	warnings: AlignmentWarning[];
1028→}
1029→
1030→/**
1031→ * Fetch validation results
1032→ * AC: @ui-validation-view ac-1
1033→ */
1034→export async function fetchValidation(): Promise<ValidationResponse> {
1035→	if (isStaticMode()) {
1036→		return {
1037→			valid: true,
1038→			schemaErrors: [],
1039→			refErrors: [],
1040→			refWarnings: [],
1041→			orphans: [],
1042→			completenessWarnings: [],
1043→			traitCycles: []
1044→		};
1045→	}
1046→
1047→	const response = await fetch(`${API_BASE}/api/validate`, {
1048→		headers: getProjectHeaders()
1049→	});
1050→	if (!response.ok) {
1051→		await handleResponseError(response);
1052→	}
1053→
1054→	return response.json();
1055→}
1056→
1057→/**
1058→ * Fetch alignment stats and warnings
1059→ * AC: @ui-validation-view ac-1
1060→ */
1061→export async function fetchAlignment(): Promise<AlignmentResponse> {
1062→	if (isStaticMode()) {
1063→		return {
1064→			stats: { totalSpecs: 0, specsWithTasks: 0, alignedSpecs: 0, orphanedSpecs: 0 },
1065→			warnings: []
1066→		};
1067→	}
1068→
1069→	const response = await fetch(`${API_BASE}/api/alignment`, {
1070→		headers: getProjectHeaders()
1071→	});
1072→	if (!response.ok) {
1073→		await handleResponseError(response);
1074→	}
1075→
1076→	return response.json();
1077→}
