/**
 * Active invocation from GET /api/agent/status
 */
export interface ActiveInvocation {
	session_id: string;
	agent_id: string;
	task_ref: string | null;
	elapsed_ms: number;
}

/**
 * Agent dispatch status from GET /api/agent/status
 */
export interface AgentDispatchStatus {
