 */
export interface HealthResponse {
  status: string;
  uptime: number;
  connections: number;
  version: string;
}

/**
 * Convention from meta
 * AC: @ui-settings-view ac-1
 */
export interface ConventionItem {
  _ulid: string;
  domain: string;
  rules: string[];
  examples: Array<{ good: string; bad: string }>;
}

/**
 * Project config from manifest
 * AC: @ui-settings-view ac-1
 */
export interface ProjectConfig {
  project: { name: string; version: string; status?: string } | null;
  kynetic: string | null;
  manifestPath: string | null;
  specDir: string;
  rootDir: string;
}

/**
 * Shadow branch status
 * AC: @ui-settings-view ac-1
 */
export interface ShadowStatus {
  enabled: boolean;
  branchName: string | null;
  worktreeDir: string | null;
  projectRoot: string | null;
}

/**
 * Fetch daemon health info
 * AC: @ui-settings-view ac-1
 */
export async function fetchHealth(): Promise<HealthResponse> {
  const response = await fetch(`${API_BASE}/api/health`);
  if (!response.ok) {
    await handleResponseError(response);
  }
  return response.json();
}

/**
 * Fetch conventions from meta
 * AC: @ui-settings-view ac-1
 */
export async function fetchConventions(): Promise<{ items: ConventionItem[]; total: number }> {
  if (isStaticMode()) {
    return { items: [], total: 0 };
  }

  const response = await fetch(`${API_BASE}/api/meta/conventions`, {
    headers: getProjectHeaders()
  });
  if (!response.ok) {
    await handleResponseError(response);
  }

  return response.json();
}

/**
 * Fetch project config from manifest
 * AC: @ui-settings-view ac-1
 */
export async function fetchProjectConfig(): Promise<ProjectConfig> {
  if (isStaticMode()) {
    const snapshot = (await import('./stores/mode.svelte')).getSnapshotProject();
    return {
      project: snapshot ? { name: snapshot.name, version: snapshot.version ?? '0.1.0' } : null,
      kynetic: null,
      manifestPath: null,
      specDir: '',
      rootDir: ''
    };
  }

  const response = await fetch(`${API_BASE}/api/meta/config`, {
    headers: getProjectHeaders()
  });
  if (!response.ok) {
    await handleResponseError(response);
  }

  return response.json();
}

/**
 * Fetch shadow branch status
 * AC: @ui-settings-view ac-1
 */
export async function fetchShadowStatus(): Promise<ShadowStatus> {
  if (isStaticMode()) {
    return { enabled: false, branchName: null, worktreeDir: null, projectRoot: null };
  }

  const response = await fetch(`${API_BASE}/api/meta/shadow`, {
    headers: getProjectHeaders()
  });
  if (!response.ok) {
    await handleResponseError(response);
  }

  return response.json();
}

